PYTHON.TEXT:
	Блок
	компілятор для Pythonблоки
	компілюють, ставлячи інструкцію assign перед скомпільованим
	тілом блоку. Це присвоєння розширює поточне середовище фреймом,
	який зв’язує імена, оголошені в блоці, зі значенням
	"*unassigned*". Ця операція
	і потребує, і змінює регістр env.

          compile_block
          scanning out declarationsin compiler
	  compile_block

function compile_block(stmt, target, linkage) {
    const body = block_body(stmt);
    const locals = scan_out_declarations(body);
    const unassigneds = list_of_unassigned(locals);
    return append_instruction_sequences(
               make_instruction_sequence(list("env"), list("env"),
                   list(assign("env", list(op("extend_environment"),
                                           constant(locals),
                                           constant(unassigneds),
                                           reg("env"))))),
               compile(body, target, linkage));
}

PYTHON.EXERCISE:
        Поточний проєкт append_return_undefined
        трохи грубий: він завжди приєднує
        return undefined; до тіла лямбда-виразу, навіть якщо інструкція return уже є на кожному шляху
	виконання цього тіла. Перепишіть
        append_return_undefined так, щоб він вставляв
        return undefined; лише в кінці
	тих шляхів, які не містять інструкції return. Перевірте своє
        розв’язання на наведених далі функціях, підставивши будь-які вирази замість
        $e_1$ та
        $e_2$
        і будь-які (не-return) інструкції замість
        $s_1$ та
	$s_2$.
        У t інструкцію return слід
	додати або на обох (*), або лише на
	(**).
        У w та
	h інструкцію return слід додати
	на одному з (*).
        У m жодної інструкції return додавати не слід.


function t(b) {   function w(b) {    function m(b) {    function h(b1, b2) {
   if (b) {          if (b) {           if (b) {           if (b1) {
      $s_1~~$              return $e_1;~$         return $e_1;~$         return $e_1$;
      (*)                                                  } else {
   } else {          } else {           } else {              if (b2) {
      $s_2~~$               $s_1~~$               return $e_2$;             $s_1$
      (*)               (*)                                      (*)
   }                 }                  }                     } else {
   (**)              (*)                                         return $e_2$;
}                 }                  }                        }
                                                              (*)
                                                           }
                                                           (*)
                                                        }
